{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "► Long COVID is a heterogeneous condition with an uncertain prevalence, for which there is currently no precise case definition.",
      "reason": "The evidence describes the current state of knowledge (heterogeneity) and an important uncertainty (uncertain prevalence/no precise case definition)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Background While it is now apparent clinical sequelae (long COVID) may persist after acute COVID-19, their nature, frequency and aetiology are poorly characterised. This study aims to regularly synthesise evidence on long COVID characteristics, to help inform clinical management, rehabilitation strategies and interventional studies to improve long-­ term outcomes.",
      "reason": "The need and importance of conducting the review are explicitly explained in relation to poorly characterised nature/frequency/aetiology and its purpose to inform management and outcomes."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Systematic reviews conducted early during the COVID-­ 19 pandemic soon became redundant due to the rapidity with which new research was released.",
      "reason": "The evidence explains that earlier systematic reviews became redundant, but it does not identify and cite specific previous systematic reviews or describe the current review as an update/replication with explicit citations to prior reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence describes a living systematic review to synthesise evidence on symptoms/characteristics (not intervention effects), so a proposed mechanism of action for an intervention is not applicable for this criterion."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe a complex intervention or delivery context requiring a logic model; therefore this criterion is not applicable based on the available information."
    }
  ],
  "confidence": 78
}

