{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Peer-­ reviewed studies were considered eligible if they included at least 100 people with laboratory confirmed and/or clinically diagnosed COVID-­ 19. Without a clear, internationally agreed case definition, we included studies that reported symptoms or outcomes assessed at 12 or more weeks post COVID-­ 19 onset.",
      "reason": "The eligibility criteria specify key study characteristics used for inclusion: required participant number (≥100), case ascertainment (laboratory confirmed/clinically diagnosed COVID-19), and follow-up duration threshold (≥12 weeks post onset)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_17",
      "quote": "We identified 6459 studies, of which 39 met the inclusion criteria (online supplemental file 3), all of which were published in English.",
      "reason": "Report-characteristic eligibility is partially specified (language: English). However, the evidence provided does not clearly specify dissemination year criteria or publication/report status criteria as part of eligibility."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided describing a distinction between exclusions where outcomes were not measured versus where outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "We presented symptom proportions by different settings, as presented in the individual studies: hospitalised, non-­ hospitalised or a mix of both populations if no subset data were available. Symptoms were broadly grouped into physiological clusters through discussion with clinicians.",
      "reason": "The evidence specifies grouping used in synthesis (settings: hospitalised vs non-hospitalised vs mix; physiological clusters). However, it does not explicitly link these groups to the comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "Studies were excluded if they included fewer than 100 participants, to avoid small study effects, 18 or the follow-­ up was unclear or less than 12 weeks post onset.",
      "reason": "Rationale is provided for the participant-size restriction (to avoid small study effects). A rationale for other notable restrictions (e.g., excluding unclear follow-up or <12 weeks) is not explicitly stated in the provided evidence."
    }
  ],
  "confidence": 72
}

